import rclpy
import os
import random
from rclpy.node import Node as ROS2BaseNode
from typing import Any, Callable, Optional, Type
from .publisher import ROS2Publisher
from .subscriber import ROS2Subscriber
from .service import ROS2Service
from .client import ROS2Client
from ..logger.logger import logger
from ..timer import Timer


class ROS2Node:

    def __init__(self, node_name: str, anonymous: bool = False, **kwargs):
        if not rclpy.ok():
            rclpy.init()

        if anonymous:
            pid = os.getpid()
            random_num = random.randint(100000, 999999)
            node_name = f"{node_name}_{pid}_{random_num}"

        self._node = ROS2BaseNode(node_name, **kwargs)
        self._publishers = {}
        self._subscribers = {}
        self._services = {}
        self._clients = {}
        self._timers = []

    def create_publisher(
        self, msg_type: Type, topic: str, qos_profile: int = 10, **kwargs
    ):
        """创建发布者"""
        publisher = ROS2Publisher(self._node, msg_type, topic, qos_profile, **kwargs)
        self._publishers[topic] = publisher
        return publisher

    def create_subscriber(
        self,
        msg_type: Type,
        topic: str,
        callback: Callable,
        qos_profile: int = 10,
        **kwargs,
    ):
        """创建订阅者"""
        subscriber = ROS2Subscriber(
            self._node, msg_type, topic, callback, qos_profile, **kwargs
        )
        if topic not in self._subscribers:
            self._subscribers[topic] = []
        self._subscribers[topic].append(subscriber)
        return subscriber

    def create_service(
        self, srv_type: Type, service_name: str, callback: Callable, **kwargs
    ):
        """创建服务端"""
        service = ROS2Service(self._node, srv_type, service_name, callback, **kwargs)
        self._services[service_name] = service
        return service

    def create_client(self, srv_type: Type, service_name: str, **kwargs):
        """创建服务客户端"""
        client = ROS2Client(self._node, srv_type, service_name, **kwargs)
        self._clients[service_name] = client
        return client

    def wait_for_service(
        self, service_name: str, timeout_sec: Optional[float] = None
    ) -> bool:
        """等待服务可用

        Args:
            service_name: 服务名称
            timeout_sec: 超时时间（秒），None表示无限等待

        Returns:
            服务是否可用
        """
        if service_name in self._clients:
            return self._clients[service_name].wait_for_service(timeout_sec=timeout_sec)
        else:
            from std_srvs.srv import Empty

            temp_client = ROS2Client(self._node, Empty, service_name)
            result = temp_client.wait_for_service(timeout_sec=timeout_sec)
            temp_client.destroy()
            return result

    def declare_parameter(self, name: str, value: Any = None, **kwargs):
        """声明参数"""
        return self._node.declare_parameter(name, value, **kwargs)

    def get_parameter(
        self, name: str, default: Any = None, node_name: Optional[str] = None
    ):
        """获取参数

        Args:
            name: 参数名称
            default: 默认值
            node_name: 节点名称，如果指定则获取其他节点的参数，否则获取当前节点的参数
        """
        if node_name:
            # 获取其他节点的参数
            from rcl_interfaces.srv import GetParameters

            # 创建临时客户端
            client = self._node.create_client(
                GetParameters, f"/{node_name}/get_parameters"
            )

            if not client.wait_for_service(timeout_sec=5.0):
                logger.warning(f"无法连接到节点 {node_name} 的参数服务")
                return default

            # 请求参数
            request = GetParameters.Request()
            request.names = [name]

            future = client.call_async(request)

            # 等待结果（节点会在其他线程spin）
            import time

            timeout = 5.0
            start_time = time.time()
            while not future.done() and (time.time() - start_time) < timeout:
                time.sleep(0.01)

            if future.result() is not None and len(future.result().values) > 0:
                param_value = future.result().values[0]
                # 根据参数类型返回值
                if param_value.type == 1:  # PARAMETER_BOOL
                    return param_value.bool_value
                elif param_value.type == 2:  # PARAMETER_INTEGER
                    return param_value.integer_value
                elif param_value.type == 3:  # PARAMETER_DOUBLE
                    return param_value.double_value
                elif param_value.type == 4:  # PARAMETER_STRING
                    return param_value.string_value
                elif param_value.type == 5:  # PARAMETER_BYTE_ARRAY
                    return param_value.byte_array_value
                elif param_value.type == 6:  # PARAMETER_BOOL_ARRAY
                    return param_value.bool_array_value
                elif param_value.type == 7:  # PARAMETER_INTEGER_ARRAY
                    return param_value.integer_array_value
                elif param_value.type == 8:  # PARAMETER_DOUBLE_ARRAY
                    return param_value.double_array_value
                elif param_value.type == 9:  # PARAMETER_STRING_ARRAY
                    return param_value.string_array_value

            self._node.destroy_client(client)
            return default
        else:
            # 获取当前节点的参数
            if self._node.has_parameter(name):
                return self._node.get_parameter(name).value
            return default

    def set_parameter(self, name: str, value: Any):
        """设置参数"""
        from rclpy.parameter import Parameter

        param = Parameter(name, value=value)
        self._node.set_parameters([param])

    def has_parameter(self, name: str) -> bool:
        """检查参数是否存在"""
        return self._node.has_parameter(name)

    def create_timer(self, period: float, callback: Callable):
        """创建定时器

        Args:
            period: 定时器周期（秒）
            callback: 回调函数
        """
        timer = Timer(period, callback)
        self._timers.append(timer)
        return timer

    def spin(self):
        """开始节点循环"""
        from rclpy.executors import SingleThreadedExecutor

        executor = SingleThreadedExecutor()
        executor.add_node(self._node)
        executor.spin()

    def destroy_node(self):
        """销毁节点"""
        for publisher in self._publishers.values():
            publisher.destroy()
        for subscriber_list in self._subscribers.values():
            for subscriber in subscriber_list:
                subscriber.destroy()
        for service in self._services.values():
            service.destroy()
        for client in self._clients.values():
            client.destroy()
        for timer in self._timers:
            timer.shutdown()
        self._publishers.clear()
        self._subscribers.clear()
        self._services.clear()
        self._clients.clear()
        self._timers.clear()
        self._node.destroy_node()
